import {resolveTargets} from './relative-navigation.js';
import {createCharge} from './power.js';
import {validateManeuverNode} from './maneuver-node.js';
import * as T from 'three';
import {Flight,statistics,validateCraft} from './core.js';
import {PARTS} from './catalog.js';
import {orbitState} from './planet.js';
import {SAS_MODES} from './navigation.js';
const flags=['started','crashed','landed','sas','brake','reactionEnabled','steeringEnabled','driveEnabled'];
const numbers={time:[0,1e12],stage:[-1,1000],throttle:[0,1],ballast:[0,1],trim:[-.6,.6],maxAltitude:[0,1e10],landedTime:[0,1e12]};
const check=(ok)=>{if(!ok)throw Error('飛行保存データの形式または値が不正です');};
const vector=(a,n,limit)=>{check(Array.isArray(a)&&a.length===n&&a.every(v=>Number.isFinite(v)&&Math.abs(v)<=limit));return a;};
const quaternion=a=>{vector(a,4,1.01);check(Math.abs(a.reduce((s,v)=>s+v*v,0)-1)<.01);return a;};
function entries(values,allowed,read){check(Array.isArray(values)&&values.length<=400);const out=new Map();for(const row of values){check(Array.isArray(row)&&row.length===2&&allowed.has(row[0])&&!out.has(row[0]));out.set(row[0],read(row[1],row[0]));}return out;}
export function saveFlight(f,meta={}){const state={};for(const k of [...flags,...Object.keys(numbers)])state[k]=f[k];return structuredClone({kind:'orbital-foundry-flight',version:1,parts:structuredClone(f.parts),environment:f.environment,pos:f.pos.toArray(),vel:f.vel.toArray(),q:f.q.toArray(),omega:f.omega.toArray(),holdQ:f.holdQ?.toArray()||null,sasMode:f.sasMode,targetPartId:f.targetPartId,dockingPorts:f.dockingPorts,portTranslationEnabled:f.portTranslationEnabled,maneuver:f.maneuver||null,state,rcsEnabled:f.rcsEnabled,fuel:[...f.fuel],charge:[...f.charge],active:[...f.active],deflections:[...f.deflections],gimbals:[...f.gimbals].map(([k,v])=>[k,v.toArray()]),wheelMotion:[...f.wheelMotion],chutes:[...f.chutes],detached:f.detached.map(child=>saveFlight(child)),meta});}
export function loadFlight(value,{debris=false,depth=0,budget={count:0,ids:new Set()}}={}){check(depth<=32);check(value?.kind==='orbital-foundry-flight'&&value.version===1);const parts=validateCraft({version:1,parts:value.parts}),byId=new Map(parts.map(p=>[p.id,p]));check(parts.filter(p=>!p.parent).length===1&&(debris||parts.some(p=>PARTS[p.type].control)));budget.count+=parts.length;check(budget.count<=400);for(const p of parts){check(!budget.ids.has(p.id));budget.ids.add(p.id);}const children=value.detached??[];check(Array.isArray(children)&&children.length<=400);check(['land','runway','water','orbit','drop'].includes(value.environment));vector(value.pos,3,1e10);vector(value.vel,3,1e6);vector(value.omega,3,1e4);quaternion(value.q);if(value.holdQ!==null)quaternion(value.holdQ);check(Object.hasOwn(SAS_MODES,value.sasMode));check(value.state&&typeof value.state==='object');for(const k of flags)check(typeof value.state[k]==='boolean');for(const [k,[min,max]]of Object.entries(numbers))check(Number.isFinite(value.state[k])&&value.state[k]>=min&&value.state[k]<=max);check(Number.isInteger(value.state.stage));const ids=new Set(byId.keys()),tankIds=new Set(parts.filter(p=>PARTS[p.type].fuel||PARTS[p.type].monoprop).map(p=>p.id));const fuel=entries(value.fuel,tankIds,(v,id)=>{check(Number.isFinite(v)&&v>=0&&v<=(PARTS[byId.get(id).type].fuel||PARTS[byId.get(id).type].monoprop));return v;});check(fuel.size===tankIds.size);check(Array.isArray(value.active)&&value.active.length<=400&&new Set(value.active).size===value.active.length&&value.active.every(id=>byId.has(id)&&PARTS[byId.get(id).type].thrust));const deflections=entries(value.deflections,ids,v=>{check(Number.isFinite(v)&&Math.abs(v)<=Math.PI);return v;}),gimbals=entries(value.gimbals,ids,v=>new T.Vector3(...vector(v,3,Math.PI))),wheelMotion=entries(value.wheelMotion,ids,v=>{check(v&&['angle','speed','steer'].every(k=>Number.isFinite(v[k])&&Math.abs(v[k])<1e6));return {angle:v.angle,speed:v.speed,steer:v.steer};}),chuteIds=new Set(parts.filter(p=>PARTS[p.type].parachute).map(p=>p.id)),chutes=entries(value.chutes,chuteIds,v=>{check(v&&['stowed','armed','reefed','open','landed'].includes(v.status)&&Number.isFinite(v.fraction)&&v.fraction>=0&&v.fraction<=1);return {status:v.status,fraction:v.fraction};});check(chutes.size===chuteIds.size);
 const batteryIds=new Set(parts.filter(p=>PARTS[p.type].battery).map(p=>p.id)),charge=value.charge===undefined?createCharge(parts):entries(value.charge,batteryIds,(v,id)=>{check(Number.isFinite(v)&&v>=0&&v<=PARTS[byId.get(id).type].battery);return v;});check(charge.size===batteryIds.size);const maneuver=validateManeuverNode(value.maneuver);check(value.sasMode!=='maneuver'||maneuver!==null);
 check(value.rcsEnabled===undefined||typeof value.rcsEnabled==='boolean');
 check(value.targetPartId===undefined||value.targetPartId===null||(typeof value.targetPartId==='string'&&value.targetPartId.length<=200));
 check(value.dockingPorts===undefined||value.dockingPorts===null||(typeof value.dockingPorts==='object'&&['own','target'].every(k=>typeof value.dockingPorts[k]==='string'&&value.dockingPorts[k].length<=200)));check(value.portTranslationEnabled===undefined||typeof value.portTranslationEnabled==='boolean');
 const f=new Flight(parts,value.environment);f.dockingPorts=value.dockingPorts?structuredClone(value.dockingPorts):null;f.portTranslationEnabled=value.portTranslationEnabled??false;f.targetPartId=value.targetPartId??null;f.rcsEnabled=value.rcsEnabled??false;f.maneuver=maneuver;for(const k of [...flags,...Object.keys(numbers)])f[k]=value.state[k];f.pos.fromArray(value.pos);f.vel.fromArray(value.vel);f.q.fromArray(value.q).normalize();f.omega.fromArray(value.omega);f.holdQ=value.holdQ?new T.Quaternion().fromArray(value.holdQ).normalize():f.q.clone();f.sasMode=value.sasMode;f.fuel=fuel;f.charge=charge;f.active=new Set(value.active);f.deflections=deflections;f.gimbals=gimbals;f.wheelMotion=wheelMotion;f.chutes=chutes;f.buildColliders();f.stats=statistics(f.parts,f.fuel,f.ballast);f.orbit=orbitState(f.pos.clone().add(f.stats.com.clone().applyQuaternion(f.q)),f.vel);try{for(const child of children)f.detached.push(loadFlight(child,{debris:true,depth:depth+1,budget}));if(depth===0)resolveTargets(f,{strict:true});}catch(error){f.dispose();throw error;}return f;}
